CREATE DATABASE IF NOT EXISTS ideare_staff_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE ideare_staff_db;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS announcement_reads;DROP TABLE IF EXISTS notifications;DROP TABLE IF EXISTS announcements;DROP TABLE IF EXISTS activity_logs;DROP TABLE IF EXISTS design_assignments;DROP TABLE IF EXISTS tasks;DROP TABLE IF EXISTS salary_records;DROP TABLE IF EXISTS salary_advances;DROP TABLE IF EXISTS overtime_requests;DROP TABLE IF EXISTS leave_requests;DROP TABLE IF EXISTS leave_types;DROP TABLE IF EXISTS attendance;DROP TABLE IF EXISTS password_reset_tokens;DROP TABLE IF EXISTS role_permissions;DROP TABLE IF EXISTS permissions;DROP TABLE IF EXISTS staff;DROP TABLE IF EXISTS roles;DROP TABLE IF EXISTS departments;DROP TABLE IF EXISTS branches;DROP TABLE IF EXISTS system_settings;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE branches(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,code VARCHAR(30) NOT NULL UNIQUE,city VARCHAR(100),state VARCHAR(100),is_active TINYINT(1) DEFAULT 1);
CREATE TABLE departments(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,description TEXT,is_active TINYINT(1) DEFAULT 1);
CREATE TABLE roles(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,slug VARCHAR(100) NOT NULL UNIQUE,description TEXT,hierarchy_level INT DEFAULT 100,is_active TINYINT(1) DEFAULT 1);
CREATE TABLE permissions(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,permission_key VARCHAR(150) NOT NULL UNIQUE,description TEXT);
CREATE TABLE staff(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,staff_code VARCHAR(30) NOT NULL UNIQUE,role_id INT UNSIGNED NOT NULL,department_id INT UNSIGNED,branch_id INT UNSIGNED,first_name VARCHAR(100) NOT NULL,last_name VARCHAR(100),email VARCHAR(180) NOT NULL UNIQUE,phone VARCHAR(50),password_hash VARCHAR(255) NOT NULL,profile_photo VARCHAR(255),job_title VARCHAR(150),hire_date DATE,date_of_birth DATE,address TEXT,emergency_contact_name VARCHAR(150),emergency_contact_phone VARCHAR(50),employment_status ENUM('active','inactive','probation','resigned','terminated') DEFAULT 'active',must_change_password TINYINT(1) DEFAULT 1,last_login_at DATETIME,failed_login_attempts INT DEFAULT 0,locked_until DATETIME,is_active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(role_id) REFERENCES roles(id),FOREIGN KEY(department_id) REFERENCES departments(id) ON DELETE SET NULL,FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL);
CREATE TABLE role_permissions(role_id INT UNSIGNED NOT NULL,permission_id INT UNSIGNED NOT NULL,PRIMARY KEY(role_id,permission_id),FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE,FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE);
CREATE TABLE password_reset_tokens(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,staff_id INT UNSIGNED NOT NULL,token_hash VARCHAR(255) NOT NULL,expires_at DATETIME NOT NULL,used_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(staff_id) REFERENCES staff(id) ON DELETE CASCADE);
CREATE TABLE attendance(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,staff_id INT UNSIGNED NOT NULL,attendance_date DATE NOT NULL,clock_in DATETIME,clock_out DATETIME,break_minutes INT DEFAULT 0,status ENUM('present','late','absent','half_day','leave','off_day') DEFAULT 'present',notes TEXT,approved_by INT UNSIGNED,approved_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY unique_staff_attendance(staff_id,attendance_date),FOREIGN KEY(staff_id) REFERENCES staff(id) ON DELETE CASCADE,FOREIGN KEY(approved_by) REFERENCES staff(id) ON DELETE SET NULL);
CREATE TABLE leave_types(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,code VARCHAR(30) NOT NULL UNIQUE,default_days DECIMAL(5,2) DEFAULT 0,paid_leave TINYINT(1) DEFAULT 1,requires_document TINYINT(1) DEFAULT 0,is_active TINYINT(1) DEFAULT 1);
CREATE TABLE leave_requests(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,staff_id INT UNSIGNED NOT NULL,leave_type_id INT UNSIGNED NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,total_days DECIMAL(5,2) NOT NULL,reason TEXT NOT NULL,attachment_path VARCHAR(255),status ENUM('pending','approved','rejected','cancelled') DEFAULT 'pending',reviewed_by INT UNSIGNED,reviewed_at DATETIME,reviewer_notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(staff_id) REFERENCES staff(id) ON DELETE CASCADE,FOREIGN KEY(leave_type_id) REFERENCES leave_types(id),FOREIGN KEY(reviewed_by) REFERENCES staff(id) ON DELETE SET NULL);
CREATE TABLE overtime_requests(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,staff_id INT UNSIGNED NOT NULL,overtime_date DATE NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,total_hours DECIMAL(5,2) NOT NULL,reason TEXT NOT NULL,status ENUM('pending','approved','rejected','cancelled') DEFAULT 'pending',reviewed_by INT UNSIGNED,reviewed_at DATETIME,reviewer_notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(staff_id) REFERENCES staff(id) ON DELETE CASCADE,FOREIGN KEY(reviewed_by) REFERENCES staff(id) ON DELETE SET NULL);
CREATE TABLE salary_advances(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,staff_id INT UNSIGNED NOT NULL,amount DECIMAL(12,2) NOT NULL,reason TEXT NOT NULL,repayment_notes TEXT,status ENUM('pending','approved','rejected','paid','cancelled') DEFAULT 'pending',reviewed_by INT UNSIGNED,reviewed_at DATETIME,reviewer_notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(staff_id) REFERENCES staff(id) ON DELETE CASCADE,FOREIGN KEY(reviewed_by) REFERENCES staff(id) ON DELETE SET NULL);
CREATE TABLE salary_records(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,staff_id INT UNSIGNED NOT NULL,salary_month TINYINT UNSIGNED NOT NULL,salary_year SMALLINT UNSIGNED NOT NULL,basic_salary DECIMAL(12,2) DEFAULT 0,overtime_amount DECIMAL(12,2) DEFAULT 0,allowance_amount DECIMAL(12,2) DEFAULT 0,commission_amount DECIMAL(12,2) DEFAULT 0,bonus_amount DECIMAL(12,2) DEFAULT 0,deduction_amount DECIMAL(12,2) DEFAULT 0,advance_deduction DECIMAL(12,2) DEFAULT 0,net_salary DECIMAL(12,2) DEFAULT 0,notes TEXT,payment_status ENUM('draft','approved','paid') DEFAULT 'draft',payment_date DATE,created_by INT UNSIGNED,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY unique_salary_month(staff_id,salary_month,salary_year),FOREIGN KEY(staff_id) REFERENCES staff(id) ON DELETE CASCADE,FOREIGN KEY(created_by) REFERENCES staff(id) ON DELETE SET NULL);
CREATE TABLE tasks(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200) NOT NULL,description TEXT,assigned_to INT UNSIGNED,assigned_by INT UNSIGNED,priority ENUM('low','normal','high','urgent') DEFAULT 'normal',status ENUM('todo','in_progress','waiting','completed','cancelled') DEFAULT 'todo',due_date DATETIME,completed_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(assigned_to) REFERENCES staff(id) ON DELETE SET NULL,FOREIGN KEY(assigned_by) REFERENCES staff(id) ON DELETE SET NULL);
CREATE TABLE design_assignments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,design_id INT UNSIGNED,design_code VARCHAR(50) NOT NULL,assigned_to INT UNSIGNED NOT NULL,assigned_by INT UNSIGNED,assignment_type ENUM('consultation','design','quotation','review','installation','follow_up') DEFAULT 'design',status ENUM('assigned','in_progress','waiting_customer','completed','cancelled') DEFAULT 'assigned',notes TEXT,assigned_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,completed_at DATETIME,FOREIGN KEY(assigned_to) REFERENCES staff(id) ON DELETE CASCADE,FOREIGN KEY(assigned_by) REFERENCES staff(id) ON DELETE SET NULL);
CREATE TABLE announcements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200) NOT NULL,content TEXT NOT NULL,created_by INT UNSIGNED,target_role_id INT UNSIGNED,is_important TINYINT(1) DEFAULT 0,publish_at DATETIME,expires_at DATETIME,is_active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(created_by) REFERENCES staff(id) ON DELETE SET NULL,FOREIGN KEY(target_role_id) REFERENCES roles(id) ON DELETE SET NULL);
CREATE TABLE announcement_reads(announcement_id BIGINT UNSIGNED NOT NULL,staff_id INT UNSIGNED NOT NULL,read_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(announcement_id,staff_id),FOREIGN KEY(announcement_id) REFERENCES announcements(id) ON DELETE CASCADE,FOREIGN KEY(staff_id) REFERENCES staff(id) ON DELETE CASCADE);
CREATE TABLE notifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,staff_id INT UNSIGNED NOT NULL,title VARCHAR(200) NOT NULL,message TEXT NOT NULL,notification_type VARCHAR(50),related_type VARCHAR(50),related_id BIGINT UNSIGNED,is_read TINYINT(1) DEFAULT 0,read_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(staff_id) REFERENCES staff(id) ON DELETE CASCADE);
CREATE TABLE activity_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,staff_id INT UNSIGNED,action VARCHAR(150) NOT NULL,entity_type VARCHAR(100),entity_id VARCHAR(100),description TEXT,ip_address VARCHAR(45),user_agent TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(staff_id) REFERENCES staff(id) ON DELETE SET NULL);
CREATE TABLE system_settings(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,setting_key VARCHAR(150) NOT NULL UNIQUE,setting_value TEXT,description TEXT,updated_by INT UNSIGNED,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(updated_by) REFERENCES staff(id) ON DELETE SET NULL);




